MSG_SET = set(MSG_VARIANTS)
EXPECTED_LIST = ", ".join(f"`{x}`" for x in MSG_VARIANTS)

STRING_PAYLOADS = {
    "FocusPath", "FocusPathFromInput", "FocusByFileName", "ChangeDirectory", "SetVroot",
    "SetInputPrompt", "UpdateInputBuffer", "BufferInput", "SetInputBuffer",
    "SwitchMode", "SwitchModeKeepingInputBuffer", "SwitchModeBuiltin", "SwitchModeBuiltinKeepingInputBuffer",
    "SwitchModeCustom", "SwitchModeCustomKeepingInputBuffer", "SwitchLayout", "SwitchLayoutBuiltin", "SwitchLayoutCustom",
    "SelectPath", "UnSelectPath", "ToggleSelectionByPath", "AddNodeFilterFromInput", "RemoveNodeFilterFromInput",
    "Search", "SearchFromInput", "SearchFuzzy", "SearchFuzzyFromInput", "SearchFuzzyUnordered", "SearchFuzzyUnorderedFromInput",
    "SearchRegex", "SearchRegexFromInput", "SearchRegexUnordered", "SearchRegexUnorderedFromInput",
    "LogInfo", "LogSuccess", "LogWarning", "LogError", "Debug", "LuaEval", "LuaEvalSilently", "CallLua", "CallLuaSilently",
    "BashExec", "BashExec0", "BashExecSilently", "BashExecSilently0",
}
USIZE_PAYLOADS = {"FocusByIndex", "FocusNextByRelativeIndex", "FocusPreviousByRelativeIndex"}
COMMAND_PAYLOADS = {"Call", "Call0", "CallSilently", "CallSilently0"}

class XplrError(Exception):
    pass

class MsgError(Exception):
    pass

def eprint(msg):
    sys.stderr.write(msg)
    if not msg.endswith("\n"):
        sys.stderr.write("\n")

def abs_path(p, base=None):
    if base is None:
        base = os.getcwd()
    return os.path.abspath(os.path.join(base, os.path.expanduser(p)))

def path_error(p):
    return f"error: path doesn't exist: {abs_path(p)}"

def invalid_arg(arg):
    return f"error: invalid argument: \"{arg}\", try `-- \"{arg}\"` or `--help`"

def usage_error(flag, name):
    return f"error: usage: xplr {flag} {name}"

def split_stdin(read0):
    data = sys.stdin.buffer.read()
    sep = b"\0" if read0 else b"\n"
    parts = data.split(sep)
    if parts and parts[-1] == b"":
        parts = parts[:-1]
    return [p.decode(errors="surrogateescape") for p in parts]

def load_config(paths, opts):
    for p in paths:
        try:
            txt = open(p, "r", encoding="utf-8", errors="ignore").read()
        except FileNotFoundError:
            raise XplrError(path_error(p))
        # Tiny subset of the Lua config that commonly appears in examples.
        if re.search(r"xplr\.config\.general\.show_hidden\s*=\s*true", txt):
            opts["show_hidden"] = True
        if re.search(r"xplr\.config\.general\.show_hidden\s*=\s*false", txt):
            opts["show_hidden"] = False
        if re.search(r"xplr\.config\.general\.read_only\s*=\s*true", txt):
            opts["read_only"] = True
        if re.search(r"xplr\.config\.general\.read_only\s*=\s*false", txt):
            opts["read_only"] = False
        # Observe simple startup messages declared in Lua tables.
        for m in re.findall(r"['\"]([A-Za-z][A-Za-z0-9_]*(?::[^'\"]*)?)['\"]", txt):
            if m.split(":",1)[0] in MSG_SET and "on_load" in txt:
                opts.setdefault("on_load", []).append(m)

def substitute_template(fmt, vals, mode_flag):
    out = []
    vi = 0
    i = 0
    while i < len(fmt):
        ch = fmt[i]
        if ch != "%":
            out.append(ch); i += 1; continue
        col = i + 1
        if i + 1 >= len(fmt):
            raise MsgError(f"error: xplr -m: template ended with incomplete placeholder")
        code = fmt[i+1]
        if code == "%":
            out.append("%"); i += 2; continue
        if code not in ("s", "q"):
            raise MsgError(f"error: xplr -m: invalid placeholder '%{code}' at column {col}, use one of '%s' or '%q', or escape it using '%%'")
        if vi >= len(vals):
            raise MsgError(f"error: xplr -m: placeholder missing value at column {col}")
        v = vals[vi]; vi += 1
        if code == "s":
            out.append(v)
        else:
            out.append(json.dumps(v, ensure_ascii=False, separators=(",",":")))
        i += 2
    if vi < len(vals):
        raise MsgError("error: xplr -m: too many positional values, not enough positional placeholders")
    return "".join(out)

def unquote_scalar(s):
    s = s.strip()
    if not s:
        return None
    if (s[0] == s[-1:] == '"') or (s[0] == s[-1:] == "'"):
        if s[0] == '"':
            try: return json.loads(s)
            except Exception: pass
        try: return ast.literal_eval(s)
        except Exception: return s[1:-1]
    if s.lower() == "true": return True
    if s.lower() == "false": return False
    if re.fullmatch(r"[-+]?\d+", s):
        return int(s)
    return s

def yamlish_to_python(s):
    s = s.strip()
    if not s:
        return None
    if s[0] in "[{":
        # Convert a small YAML/JSON-ish subset: unquoted keys in maps.
        t = s
        t = re.sub(r"([\{,]\s*)([A-Za-z_][A-Za-z0-9_]*)\s*:", r'\1"\2":', t)
        # Quote bare words in lists/map values, but keep numbers/booleans/null.
        def repl_bare(m):
            pre, word = m.group(1), m.group(2)
            if word in ("true","false","null") or re.fullmatch(r"[-+]?\d+", word):
                return pre + word
            return pre + json.dumps(word)
        t = re.sub(r"(:\s*|\[\s*|,\s*)([A-Za-z_./~-][A-Za-z0-9_./~+-]*)\s*(?=[,\]\}])", repl_bare, t)
        try:
            return json.loads(t)
        except Exception:
            try: return ast.literal_eval(t)
            except Exception: return s
    return unquote_scalar(s)

def parse_message(text):
    raw = text.strip()
    if not raw:
        raise MsgError("error: invalid type: unit value, expected enum ExternalMsg at line 1 column 1")
    # Serde-yaml accepts a bare variant name.
    if ":" not in raw:
        if raw in MSG_SET:
            return raw, None
        raise MsgError(f"error: unknown variant `{raw}`, expected one of {EXPECTED_LIST} at line 1 column {len(raw)+1}")
    key, val = raw.split(":", 1)
    key = key.strip()
    if key not in MSG_SET:
        raise MsgError(f"error: unknown variant `{key}`, expected one of {EXPECTED_LIST} at line 1 column {len(key)+1}")
    value = yamlish_to_python(val)
    if key in STRING_PAYLOADS:
        if value is None:
            value = ""
        if not isinstance(value, str):
            value = str(value).lower() if isinstance(value, bool) else str(value)
    elif key in USIZE_PAYLOADS:
        if not isinstance(value, int):
            raise MsgError(f"error: {key}: invalid type: string, expected usize at line 1 column {len(key)+2}")
        if value < 0:
            raise MsgError(f"error: invalid value: integer `{value}`, expected usize at line 1 column {len(key)+len(str(value))+4}")
    elif key in COMMAND_PAYLOADS:
        if not isinstance(value, dict):
            raise MsgError(f"error: invalid type: string {json.dumps(str(value))}, expected struct Command at line 1 column {len(raw)+1}")
        value.setdefault("args", [])
    return key, value

def message_to_json(text):
    k, v = parse_message(text)
    if v is None:
        return json.dumps(k, separators=(",",":"), ensure_ascii=False)
    return json.dumps({k: v}, separators=(",",":"), ensure_ascii=False)

def handle_msg_mode(args, pipe_mode=False):
    flag = "-m" if pipe_mode else "-M"
    if not args:
        raise MsgError(f"error: usage: xplr {flag} FORMAT [ARGUMENT]...")
    fmt, vals = args[0], args[1:]
    msg = substitute_template(fmt, vals, flag)
    out = message_to_json(msg)
    if pipe_mode:
        # The real tool writes into the active xplr FIFO when one is available;
        # outside a session its observable behaviour is to print the message.
        sys.stdout.write(out + "\n")
    else:
        sys.stdout.write(out)
    return 0

class State:
    def __init__(self, opts):
        self.opts = opts
        self.cwd = os.getcwd()
        self.pwd = self.cwd
        self.focus = None
        self.selection = []
        self.show_hidden = opts.get("show_hidden", False)
        self.read_only = opts.get("read_only", False)
        self.vroot = opts.get("vroot")
        self.print_pwd_as_result = opts.get("print_pwd_as_result", False)
        self.write0 = opts.get("write0", False)
        self.changed_dir = False
        self.logs = []
    def sep(self):
        return "\0" if self.write0 else "\n"

def children(path, show_hidden=False):
    try:
        names = os.listdir(path)
    except Exception:
        return []
    if not show_hidden:
        names = [n for n in names if not n.startswith('.')]
    def key(n):
        p = os.path.join(path, n)
        isdir = os.path.isdir(p)
        return (0 if isdir else 1, n.lower())
    return [os.path.join(path, n) for n in sorted(names, key=key)]

def init_state(opts, positionals):
    st = State(opts)
    p = positionals[0] if positionals else "."
    ap = abs_path(p)
    if not os.path.exists(ap):
        raise XplrError(path_error(p))
    force = opts.get("force_focus", False)
    if os.path.isdir(ap) and not force:
        st.pwd = ap
        ch = children(ap, st.show_hidden)
        st.focus = ch[0] if ch else ap
    else:
        st.pwd = os.path.dirname(ap) or os.sep
        st.focus = ap
    sels = []
    for s in positionals[1:]:
        sp = abs_path(s)
        if not os.path.exists(sp):
            raise XplrError(path_error(s))
        sels.append(sp)
    st.selection = sels
    return st

def focus_index(st):
    ch = children(st.pwd, st.show_hidden)
    try: return ch.index(st.focus), ch
    except ValueError: return (0 if ch else -1), ch

def set_focus_by_index(st, idx):
    ch = children(st.pwd, st.show_hidden)
    if ch:
        idx = max(0, min(idx, len(ch)-1))
        st.focus = ch[idx]

def execute_message(st, msg):
    k, v = parse_message(msg)
    if k in ("Quit", "Terminate"):
        return "quit"
    if k == "PrintPwdAndQuit": return "print_pwd"
    if k == "PrintFocusPathAndQuit": return "print_focus"
    if k == "PrintSelectionAndQuit": return "print_selection"
    if k == "PrintResultAndQuit": return "print_result"
    if k == "PrintAppStateAndQuit": return "print_state"
    if k == "FocusNext":
        i, ch = focus_index(st)
        if ch: st.focus = ch[min(i+1, len(ch)-1)]
    elif k == "FocusPrevious":
        i, ch = focus_index(st)
        if ch: st.focus = ch[max(i-1, 0)]
    elif k == "FocusFirst": set_focus_by_index(st, 0)
    elif k == "FocusLast":
        ch = children(st.pwd, st.show_hidden); 
        if ch: st.focus = ch[-1]
    elif k == "FocusByIndex": set_focus_by_index(st, int(v))
    elif k == "FocusPath":
        fp = abs_path(v, st.pwd)
        if os.path.exists(fp):
            st.focus = fp
            st.pwd = os.path.dirname(fp) if not os.path.isdir(fp) else os.path.dirname(fp)
    elif k == "ChangeDirectory":
        dp = abs_path(v, st.pwd)
        if os.path.isdir(dp):
            st.pwd = dp; st.changed_dir = True
            ch = children(dp, st.show_hidden); st.focus = ch[0] if ch else dp
    elif k in ("Enter", "FollowSymlink"):
        if st.focus and os.path.isdir(st.focus):
            st.pwd = st.focus; st.changed_dir = True
            ch = children(st.pwd, st.show_hidden); st.focus = ch[0] if ch else st.pwd
    elif k == "Back":
        parent = os.path.dirname(st.pwd.rstrip(os.sep)) or os.sep
        if st.vroot and not os.path.commonpath([st.vroot, parent]).startswith(st.vroot):
            return None
        old = st.pwd; st.pwd = parent; st.focus = old; st.changed_dir = True
    elif k == "Select":
        if st.focus and st.focus not in st.selection: st.selection.append(st.focus)
    elif k == "SelectAll":
        st.selection = children(st.pwd, st.show_hidden)
    elif k == "ClearSelection" or k == "UnSelectAll":
        st.selection = []
    elif k in ("SelectPath", "ToggleSelectionByPath"):
        sp = abs_path(v, st.pwd)
        if k == "ToggleSelectionByPath" and sp in st.selection: st.selection.remove(sp)
        elif sp not in st.selection: st.selection.append(sp)
    elif k == "UnSelectPath":
        sp = abs_path(v, st.pwd)
        if sp in st.selection: st.selection.remove(sp)
    elif k.startswith("Log"):
        st.logs.append((k[3:].upper(), v))
    elif k in ("ToggleMouse", "EnableMouse", "DisableMouse", "Refresh", "ClearScreen"):
        pass
    return None

def term_enter():
    sys.stdout.write("\x1b[?1049h\x1b[?25l\x1b[2J")
    sys.stdout.flush()

def term_leave():
    sys.stdout.write("\x1b[2J\x1b[1;1H\x1b[?1049l\x1b[?1006l\x1b[?1015l\x1b[?1003l\x1b[?1002l\x1b[?1000l\x1b[?25h")
    sys.stdout.flush()

def osc7(path):
    host = socket.gethostname()
    sys.stdout.write(f"\x1b]7;file://{host}{path}\x1b\\")

def print_paths(paths, st):
    sep = st.sep()
    for p in paths:
        sys.stdout.write(p + sep)
    sys.stdout.flush()

def print_result(kind, st):
    if st.changed_dir:
        osc7(st.pwd)
    if kind == "print_pwd":
        print_paths([st.pwd], st)
    elif kind == "print_focus":
        print_paths([st.focus or st.pwd], st)
    elif kind == "print_selection":
        print_paths(st.selection, st)
    elif kind == "print_result":
        if st.selection:
            print_paths(st.selection, st)
        elif st.print_pwd_as_result:
            print_paths([st.pwd], st)
        else:
            print_paths([st.focus or st.pwd], st)
    elif kind == "print_state":
        sys.stdout.write(app_state_yaml(st))
        if not st.write0: sys.stdout.write("\n")
        sys.stdout.flush()

def app_state_yaml(st):
    # A compact but recognizable app-state dump.
    lines = [
        f"bin: {abs_path(sys.argv[0])}",
        f"version: {VERSION}",
        "config:",
        "  general:",
        f"    disable_debug_error_mode: false",
        f"    enable_mouse: false",
        f"    show_hidden: {'true' if st.show_hidden else 'false'}",
        f"    read_only: {'true' if st.read_only else 'false'}",
        "    enable_recover_mode: false",
        "    hide_remaps_in_help_menu: false",
        "    enforce_bounded_index_navigation: false",
        "    prompt:",
        "      format: '❯ '",
        "app:",
        f"  pwd: {st.pwd}",
        f"  focus: {st.focus or ''}",
        "  selection:",
    ]
    for s in st.selection:
        lines.append(f"  - {s}")
    lines += ["  mode: default", "  layout: default", "  input_buffer: ''"]
    return "\n".join(lines)

def render_tui(st):
    cols, rows = shutil.get_terminal_size((80,24))
    ch = children(st.pwd, st.show_hidden)
    i, _ = focus_index(st)
    sys.stdout.write("\x1b[2J\x1b[1;1H")
    sys.stdout.write("╭ Sort & filter (3) " + "─" * max(0, min(cols-25, 40)) + "╮")
    sys.stdout.write("\r\n│rel!^. › [c]dir↑ › [i]rel↓" + " " * 8 + "│")
    sys.stdout.write("\r\n╰" + "─" * min(cols-2, 50) + "╯\r\n")
    title = f" {st.pwd} ({len(ch)}) "
    sys.stdout.write("╭" + title + "─" * max(0, min(cols - len(title) - 2, 55)) + "╮\r\n")
    sys.stdout.write("│index  path                         perm      size    modified│\r\n")
    start = max(0, i-8)
    for n, p in enumerate(ch[start:start+max(1, rows-10)], start):
        name = os.path.basename(p) + ("/" if os.path.isdir(p) else "")
        mark = "▸" if p == st.focus else " "
        sel = "*" if p in st.selection else " "
        icon = "ð" if os.path.isdir(p) else "ƒ"
        try:
            stmode = os.stat(p)
            perm = stat.filemode(stmode.st_mode)[1:]
            size = stmode.st_size
        except Exception:
            perm = "---------"; size = 0
        line = f"│{n:<5}{mark}{sel}{icon}{name:<28.28}{perm:<10}{human_size(size):>6}│"
        sys.stdout.write(line[:cols] + "\r\n")
    sys.stdout.write("╰" + "─" * min(cols-2, 60) + "╯\r\n")
    sys.stdout.write("╭ Help [default] ──────╮\r\n")
    sys.stdout.write("│q quit  enter open    │\r\n│j/k move  space select│\r\n│? f1 global help      │\r\n╰──────────────────────╯\r\n")
    if st.logs:
        sys.stdout.write("╭ Logs [default] ──────────────────────────────────────╮\r\n")
        for lev, msg in st.logs[-3:]: sys.stdout.write(f"│{lev}: {msg}\r\n")
        sys.stdout.write("╰──────────────────────────────────────────────────────╯")
    sys.stdout.flush()

def human_size(n):
    if n < 1000: return f"{n}B"
    for u in ("KB","MB","GB","TB"):
        n /= 1000.0
        if n < 1000: return f"{n:.2g}{u}"
    return f"{n:.2g}PB"

def interactive(st):
    try:
        fd = os.open('/dev/tty', os.O_RDWR)
    except OSError:
        raise XplrError("error: No such device or address (os error 6)")
    old = None
    term_enter()
    try:
        old = termios.tcgetattr(fd)
        tty.setcbreak(fd)
        render_tui(st)
        while True:
            r,_,_ = select.select([fd], [], [], 0.5)
            if not r:
                continue
            data = os.read(fd, 16)
            if not data:
                continue
            if data in (b'q', b'\x03'):
                break
            if data in (b'j', b'\x1b[B'):
                execute_message(st, "FocusNext")
            elif data in (b'k', b'\x1b[A'):
                execute_message(st, "FocusPrevious")
            elif data in (b'g',):
                execute_message(st, "FocusFirst")
            elif data in (b'G',):
                execute_message(st, "FocusLast")
            elif data in (b' ',):
                if st.focus in st.selection: st.selection.remove(st.focus)
                else: st.selection.append(st.focus)
            elif data in (b'\r', b'\n'):
                execute_message(st, "Enter")
            elif data in (b'h', b'\x7f', b'\x1b[D'):
                execute_message(st, "Back")
            elif data in (b'.',):
                st.show_hidden = not st.show_hidden
                set_focus_by_index(st, 0)
            render_tui(st)
    finally:
        if old is not None:
            try: termios.tcsetattr(fd, termios.TCSADRAIN, old)
            except Exception: pass
        term_leave()
        try: os.close(fd)
        except Exception: pass

def parse_argv(argv):
    opts = {"read0": False, "write0": False, "force_focus": False, "read_stdin": False,
            "print_pwd_as_result": False, "read_only": False, "extra_config": [], "on_load": []}
    pos = []
    config = None
    i = 0; after_dashdash = False; help_flag = False; version_flag = False
    while i < len(argv):
        a = argv[i]
        if after_dashdash:
            pos.append(a); i += 1; continue
        if a == "--":
            after_dashdash = True; i += 1; continue
        if a in ("-M", "--print-msg-in"):
            return {"msg_mode": "print", "msg_args": argv[i+1:]}, []
        if a in ("-m", "--pipe-msg-in"):
            return {"msg_mode": "pipe", "msg_args": argv[i+1:]}, []
        if a in ("-h", "--help"):
            help_flag = True; i += 1; continue
        if a in ("-V", "--version"):
            version_flag = True; i += 1; continue
        if a == "-":
            opts["read_stdin"] = True; i += 1; continue
        if a in ("-0", "--null"):
            opts["read0"] = True; opts["write0"] = True; i += 1; continue
        if a == "--read0": opts["read0"] = True; i += 1; continue
        if a == "--write0": opts["write0"] = True; i += 1; continue
        if a == "--force-focus": opts["force_focus"] = True; i += 1; continue
        if a == "--print-pwd-as-result": opts["print_pwd_as_result"] = True; i += 1; continue
        if a == "--read-only": opts["read_only"] = True; i += 1; continue
        if a in ("-c", "--config"):
            if i+1 >= len(argv): raise XplrError(usage_error(a, "PATH"))
            config = argv[i+1]; i += 2; continue
        if a == "--vroot":
            if i+1 >= len(argv): raise XplrError(usage_error(a, "PATH"))
            opts["vroot"] = abs_path(argv[i+1]); i += 2; continue
        if a in ("-C", "--extra-config"):
            i += 1
            # Optional variadic value; collect until another flag, like the observed --on-load behaviour.
            while i < len(argv) and not argv[i].startswith('-'):
                opts["extra_config"].append(argv[i]); i += 1
            continue
        if a == "--on-load":
            i += 1
            while i < len(argv) and not argv[i].startswith('-'):
                opts["on_load"].append(argv[i]); i += 1
            continue
        if a.startswith('-'):
            raise XplrError(invalid_arg(a))
        pos.append(a); i += 1
    opts["help"] = help_flag; opts["version"] = version_flag; opts["config"] = config
    return opts, pos

def run(argv):
    try:
        opts, pos = parse_argv(argv)
        if "msg_mode" in opts:
            return handle_msg_mode(opts.get("msg_args", []), opts["msg_mode"] == "pipe")
        if opts.get("help"):
            sys.stdout.write(HELP); return 0
        if opts.get("version"):
            sys.stdout.write(f"xplr {VERSION}\n"); return 0
        # Validate config and vroot before trying the terminal.
        config_paths = []
        if opts.get("config") is not None:
            if not os.path.exists(opts["config"]): raise XplrError(path_error(opts["config"]))
            config_paths.append(opts["config"])
        else:
            default = os.path.join(os.environ.get("HOME", ""), ".config", "xplr", "init.lua")
            if default and os.path.exists(default): config_paths.append(default)
        for c in opts.get("extra_config", []):
            if not os.path.exists(c): raise XplrError(path_error(c))
            config_paths.append(c)
        if opts.get("vroot") and not os.path.exists(opts["vroot"]):
            raise XplrError(path_error(opts["vroot"]))
        if config_paths:
            load_config(config_paths, opts)
        if opts.get("read_only"):
            opts["read_only"] = True
        if opts.get("read_stdin"):
            pos = split_stdin(opts.get("read0")) + pos
        st = init_state(opts, pos)
        # The real program opens /dev/tty for UI sessions.  Reproduce the observable error.
        if not os.path.exists('/dev/tty') or (not sys.stdin.isatty() and not sys.stdout.isatty()):
            # If invoked under script(1), stdio is a tty.  Plain pipes get this error.
            raise XplrError("error: No such device or address (os error 6)")
        # Parse all on-load messages before entering alternate screen, so errors are clean.
        parsed = []
        for m in opts.get("on_load", []):
            parse_message(m); parsed.append(m)
        term_enter()
        action = None
        try:
            for m in parsed:
                action = execute_message(st, m)
                if action: break
            if action:
                term_leave(); print_result(action, st); return 0
            interactive(st)
            return 0
        finally:
            # interactive does its own leave. If we entered and fell out via exception, try to restore.
            pass
    except MsgError as ex:
        eprint(str(ex)); return 1
    except XplrError as ex:
        eprint(str(ex)); return 1
    except BrokenPipeError:
        return 1

if __name__ == "__main__":
    sys.exit(run(sys.argv[1:]))
